  ('p_5a1adf', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-6ec2ee2b89248581.webp","assetTitle":"File:August 2007, walking in Seoul 91.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6b3282', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-aa4fae554e106c0d.webp","assetTitle":"File:August 2007, walking in Seoul 97.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8963fb', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-7e63fc08b977d76b.webp","assetTitle":"File:KTX in Seoul 2.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
