  ('p_ccde0f', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-2e493c5e53301906.webp","assetTitle":"File:August 2007, walking in Seoul 17.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_af52d6', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-282dba7197fa7139.webp","assetTitle":"File:August 2007, walking in Seoul 18.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4159c6', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-a228c29af3aae401.webp","assetTitle":"File:August 2007, walking in Seoul 2.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1639c7', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-4086e1dedffbe050.webp","assetTitle":"File:August 2007, walking in Seoul 22.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_86b752', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-5e02d9e26764a07e.webp","assetTitle":"File:August 2007, walking in Seoul 23.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4e8359', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-fdf6e783659c88b1.webp","assetTitle":"File:August 2007, walking in Seoul 28.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_39c50c', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-12b0a56a1055fb9b.webp","assetTitle":"File:August 2007, walking in Seoul 31.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_7f5238', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-5b3f8c42afaed446.webp","assetTitle":"File:August 2007, walking in Seoul 32.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6dd203', '니조성에서 시작한 하루', '니조성을 둘러보며 교토 여행을 시작했다. 다음 장소로 가기 전에 사진을 한 장 남겼다.', array['교토', '니조성']::text[], '{"kind":"edited-demo","asset":"kyoto-11.webp","assetTitle":"Nijo Castle","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f1121c', '니시키 시장 한 바퀴', '니시키 시장을 천천히 걸었다. 구경할 것이 많아서 생각보다 앞으로 나아가질 못했다.', array['교토', '니시키시장']::text[], '{"kind":"edited-demo","asset":"kyoto-4.webp","assetTitle":"Nishiki Market","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_10c42a', '니시키 시장의 저녁', '시장 안을 걷다가 저녁거리를 골랐다. 이것저것 보고 나니 배가 더 고파졌다.', array['교토', '니시키시장']::text[], '{"kind":"edited-demo","asset":"kyoto-13.webp","assetTitle":"Nishiki Market","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_832f25', '후시미 이나리의 길', '도리이가 이어지는 길을 걸었다. 앞을 보고 걷다가 가끔 뒤를 돌아보면 또 다른 길처럼 느껴졌다.', array['교토', '후시미이나리']::text[], '{"kind":"edited-demo","asset":"kyoto-6.webp","assetTitle":"Fushimi Inari","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b5c9ea', '도후쿠지의 가을', '도후쿠지에서 단풍을 봤다. 서두르지 않고 천천히 둘러보기로 했다.', array['교토', '도후쿠지', '단풍']::text[], '{"kind":"edited-demo","asset":"kyoto-15.webp","assetTitle":"Tofuku-ji","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_7c5dae', '늦은 점심은 장어덮밥', '많이 걷고 나서 먹는 밥이 좋았다. 사진 한 장만 남기고 카메라를 내려놓았다.', array['교토', '장어덮밥']::text[], '{"kind":"edited-demo","asset":"kyoto-9.webp","assetTitle":"Unadon","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_9dd88e', '산넨자카를 내려가며', '산넨자카를 따라 내려왔다. 가게를 구경하다가 멈추기를 여러 번 반복했다.', array['교토', '산넨자카', '골목']::text[], '{"kind":"edited-demo","asset":"kyoto-10.webp","assetTitle":"Sannenzaka","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_437411', '야사카 고신도에서', '작은 장식들이 모여 있는 모습을 한참 봤다. 가까이에서 한 장 남기고 다시 골목으로 나왔다.', array['교토', '야사카고신도']::text[], '{"kind":"edited-demo","asset":"kyoto-14.webp","assetTitle":"Yasaka Koshindo","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_d3ae09', '기요미즈데라에서 본 가을', '기요미즈데라에 올라 단풍을 바라봤다. 한 번 찍고 카메라를 넣었다가 다시 꺼냈다.', array['교토', '기요미즈데라', '단풍']::text[], '{"kind":"edited-demo","asset":"kyoto-1.webp","assetTitle":"Kiyomizu-dera","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_34d794', '단풍 사이로', '조금 옆으로 자리를 옮겨서 다시 봤다. 같은 곳인데 사진 안에 들어오는 풍경은 달라졌다.', array['교토', '기요미즈데라', '단풍']::text[], '{"kind":"edited-demo","asset":"kyoto-2.webp","assetTitle":"Kiyomizu-dera","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_21ec44', '교토를 내려다보다', '기요미즈데라에서 교토 쪽을 바라봤다. 내려가서 걸을 길을 높은 곳에서 먼저 훑어봤다.', array['교토', '전망']::text[], '{"kind":"edited-demo","asset":"kyoto-3.webp","assetTitle":"Kyoto view from Kiyomizu-dera","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b9a6c0', '아라시야마에서', '아라시야마를 천천히 둘러봤다. 오늘은 걷는 시간을 넉넉하게 잡길 잘했다.', array['교토', '아라시야마']::text[], '{"kind":"edited-demo","asset":"kyoto-8.webp","assetTitle":"Arashiyama","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_517e5b', '커피 한 잔 쉬어 가기', '많이 걸은 날에는 앉을 곳부터 찾게 된다. 커피가 식기 전에 잠깐 쉬었다.', array['교토', '커피']::text[], '{"kind":"edited-demo","asset":"kyoto-12.webp","assetTitle":"Latte","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_81af2d', '시장에 다시 들렀다', '니시키 시장에 한 번 더 들렀다. 어제 지나쳤던 가게 앞에서 이번에는 멈췄다.', array['교토', '니시키시장']::text[], '{"kind":"edited-demo","asset":"kyoto-5.webp","assetTitle":"Nishiki Market","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
