  ('p_371f54', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f8cb24323775844a.webp","assetTitle":"File:August 2007, walking in Seoul 52.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_aca665', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-9ab89267d955f2fb.webp","assetTitle":"File:August 2007, walking in Seoul 54.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_76d50d', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-24669cbda455d5d7.webp","assetTitle":"File:August 2007, walking in Seoul 58.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_72406a', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-d473d6b12b7c3fc2.webp","assetTitle":"File:August 2007, walking in Seoul 63.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_757361', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-595ebc232d715e56.webp","assetTitle":"File:August 2007, walking in Seoul 64.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_929e03', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-e07fab4fa14e9784.webp","assetTitle":"File:August 2007, walking in Seoul 68.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_57278a', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-fddea62f82674f28.webp","assetTitle":"File:August 2007, walking in Seoul 72.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_58a3de', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-3e495dbe4d9d2779.webp","assetTitle":"File:August 2007, walking in Seoul 79.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_61f250', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-59a93b129da8a766.webp","assetTitle":"File:August 2007, walking in Seoul 82.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f24614', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-6ebf517d1a2654a7.webp","assetTitle":"File:August 2007, walking in Seoul 83.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_9d19f3', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-39479bad11a5f8c7.webp","assetTitle":"File:August 2007, walking in Seoul 85.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_d2e5c1', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-faa815db02666ec8.webp","assetTitle":"File:August 2007, walking in Seoul 9.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_70c91e', '첫 해외, 첫 사진', '나리타에서 스카이라이너를 타고 우에노까지.

첫 사진은 역 앞 편의점 간판이었다.

모든 게 조금씩
작고 깨끗했다.', array['도쿄', '첫여행']::text[], '{"kind":"prototype","asset":"tokyo-1.webp","assetTitle":"Tokyo","sourcePostIds":["anon1/tokyo-1"],"editorial":[{"journeyId":"anon1","id":"tokyo-1","stopId":"tokyo","date":"2024-10-03","title":"첫 해외, 첫 사진","sub":"편의점만 세 번 갔다.","heading":"''Tokyo''에서\n찍은 첫 장","big":["FIRST","TRIP"],"body":["나리타에서 스카이라이너를 타고 우에노까지.","첫 사진은 역 앞 편의점 간판이었다."],"story":"모든 게 조금씩\n작고 깨끗했다.","photos":["/photos/tokyo-1.jpg","/photos/tokyo-2.jpg","/photos/tokyo-3.jpg","/photos/tokyo-4.jpg"],"tags":["도쿄","첫여행"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_9bd2be', '시부야를 건너며', '신호가 바뀌자 사람들이 한꺼번에 건넜다. 나도 그 사이에 섞여 길을 건넜다.', array['도쿄', '시부야']::text[], '{"kind":"edited-demo","asset":"tokyo-3.webp","assetTitle":"Shibuya Crossing","sourcePostIds":["anon1/tokyo-1"],"editorial":[{"journeyId":"anon1","id":"tokyo-1","stopId":"tokyo","date":"2024-10-03","title":"첫 해외, 첫 사진","sub":"편의점만 세 번 갔다.","heading":"''Tokyo''에서\n찍은 첫 장","big":["FIRST","TRIP"],"body":["나리타에서 스카이라이너를 타고 우에노까지.","첫 사진은 역 앞 편의점 간판이었다."],"story":"모든 게 조금씩\n작고 깨끗했다.","photos":["/photos/tokyo-1.jpg","/photos/tokyo-2.jpg","/photos/tokyo-3.jpg","/photos/tokyo-4.jpg"],"tags":["도쿄","첫여행"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_eca011', '센소지 앞에서', '센소지 앞에서 카메라를 꺼냈다. 사람들 흐름을 따라 걷다가 옆길도 조금 둘러봤다.', array['도쿄', '센소지']::text[], '{"kind":"edited-demo","asset":"tokyo-2.webp","assetTitle":"Senso-ji","sourcePostIds":["anon1/tokyo-1"],"editorial":[{"journeyId":"anon1","id":"tokyo-1","stopId":"tokyo","date":"2024-10-03","title":"첫 해외, 첫 사진","sub":"편의점만 세 번 갔다.","heading":"''Tokyo''에서\n찍은 첫 장","big":["FIRST","TRIP"],"body":["나리타에서 스카이라이너를 타고 우에노까지.","첫 사진은 역 앞 편의점 간판이었다."],"story":"모든 게 조금씩\n작고 깨끗했다.","photos":["/photos/tokyo-1.jpg","/photos/tokyo-2.jpg","/photos/tokyo-3.jpg","/photos/tokyo-4.jpg"],"tags":["도쿄","첫여행"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_015886', '도쿄 타워를 올려다보다', '도쿄 타워 앞에서 한 장 남겼다. 걸어오는 동안 멀리 보이던 탑이 바로 위에 있었다.', array['도쿄', '도쿄타워']::text[], '{"kind":"edited-demo","asset":"tokyo-4.webp","assetTitle":"Tokyo Tower","sourcePostIds":["anon1/tokyo-1"],"editorial":[{"journeyId":"anon1","id":"tokyo-1","stopId":"tokyo","date":"2024-10-03","title":"첫 해외, 첫 사진","sub":"편의점만 세 번 갔다.","heading":"''Tokyo''에서\n찍은 첫 장","big":["FIRST","TRIP"],"body":["나리타에서 스카이라이너를 타고 우에노까지.","첫 사진은 역 앞 편의점 간판이었다."],"story":"모든 게 조금씩\n작고 깨끗했다.","photos":["/photos/tokyo-1.jpg","/photos/tokyo-2.jpg","/photos/tokyo-3.jpg","/photos/tokyo-4.jpg"],"tags":["도쿄","첫여행"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_7eba47', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-730e83b0aa33e355.webp","assetTitle":"File:August 2007, walking in Seoul 90.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_2c1682', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-94411fb02b064343.webp","assetTitle":"File:August 2007, walking in Seoul 92.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_5eed04', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-de6879b712d13ec9.webp","assetTitle":"File:August 2007, walking in Seoul 95.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c55a2f', '시계탑 앞에서', '삿포로 시계탑 앞에 섰다. 사진으로 보던 건물을 직접 보고 나니 도시에 도착한 기분이 났다.', array['삿포로', '시계탑']::text[], '{"kind":"edited-demo","asset":"sapporo-3.webp","assetTitle":"Sapporo Clock Tower 20090112.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_3e56f2', '라멘 골목에서 고른 저녁', '라멘 골목을 둘러보다 한 가게를 골랐다. 따뜻한 국물을 먹고 나니 다시 걸을 힘이 났다.', array['삿포로', '라멘']::text[], '{"kind":"edited-demo","asset":"sapporo-7.webp","assetTitle":"Ramen Alley Sapporo Japan.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_5795c1', '눈축제에 왔다', '오도리 공원의 눈 조각들을 둘러봤다. 장갑을 벗고 사진을 찍었다가 얼른 다시 꼈다.', array['삿포로', '눈축제']::text[], '{"kind":"edited-demo","asset":"sapporo-1.webp","assetTitle":"Odori Park Sapporo Snow Festival 2007.JPG","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_fc772c', '오도리 공원을 걸었다', '오도리 공원을 따라 걸었다. 쉬었다가 다시 걷기를 반복하며 하루를 보냈다.', array['삿포로', '오도리공원']::text[], '{"kind":"edited-demo","asset":"sapporo-2.webp","assetTitle":"Hokkaido Sapporo Odori Park.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b4e817', '밤에 다시 본 눈축제', '밤이 되니 눈 조각들이 낮과 다르게 보였다. 한 바퀴만 더 보고 가기로 했다.', array['삿포로', '눈축제', '야경']::text[], '{"kind":"edited-demo","asset":"sapporo-6.webp","assetTitle":"Sapporo Snow Festival Odori-Site At Night Panorama 1.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_197bbc', '오타루 운하 따라', '오타루 운하를 따라 걸었다. 다리 위에서도 멈추고 물가 쪽에서도 사진을 남겼다.', array['오타루', '운하']::text[], '{"kind":"edited-demo","asset":"sapporo-4.webp","assetTitle":"Otaru Canal Cruise (20240223).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ab9dc7', '오타루의 작은 불빛', '불빛이 있는 쪽으로 천천히 걸었다. 춥지만 조금만 더 보고 가고 싶었다.', array['오타루', '불빛']::text[], '{"kind":"edited-demo","asset":"sapporo-5.webp","assetTitle":"小樽雪あかりの路2013（Otaru Snow Light Path 2013） - panoramio (1).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ec0535', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-561aaf1ba4b30d9d.webp","assetTitle":"File:August 2007, walking in Seoul 96.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_754ed3', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-3c305c479157fd56.webp","assetTitle":"File:August 2007, walking in Seoul 99.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_01daa7', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-86761dbc7b216beb.webp","assetTitle":"File:August 2007, walking in Seoul 101.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_44ca3d', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-66caf339a11b8b7a.webp","assetTitle":"File:August 2007, walking in Seoul 102.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4ddb9d', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-0b3b82832f87f186.webp","assetTitle":"File:August 2007, walking in Seoul 104.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_aeecfe', '다시 해운대', '해운대에 오면 먼저 바다부터 보게 된다. 익숙한 풍경인데도 사진은 늘 한 장씩 더 찍는다.', array['부산', '해운대', '바다']::text[], '{"kind":"edited-demo","asset":"busan-1.webp","assetTitle":"Haeundae Beach","sourcePostIds":["anon2/busan-1"],"editorial":[{"journeyId":"anon2","id":"busan-1","stopId":"busan","date":"2025-01-24","title":"설 연휴의 해운대","sub":"KTX로 두 시간 반.","heading":"''Busan''의\n겨울 바다","big":["BLUE","WAVE"],"body":["설 연휴라 기차표 구하느라 고생했다.","해운대는 생각보다 조용했다."],"story":"어묵 국물로\n손을 녹였다.","photos":["/photos/busan-1.jpg","/photos/busan-2.jpg","/photos/busan-3.jpg","/photos/busan-4.jpg"],"tags":["부산","해운대","설"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ab9d23', '광안리 쪽으로', '광안리에서 잠깐 멈췄다. 걷던 길과 바다 쪽 풍경을 번갈아 사진에 남겼다.', array['부산', '광안리', '바다']::text[], '{"kind":"authored-demo","asset":"busan-3.webp","assetTitle":"Gwangan Bridge","sourcePostIds":["anon2/busan-1"],"editorial":[{"journeyId":"anon2","id":"busan-1","stopId":"busan","date":"2025-01-24","title":"설 연휴의 해운대","sub":"KTX로 두 시간 반.","heading":"''Busan''의\n겨울 바다","big":["BLUE","WAVE"],"body":["설 연휴라 기차표 구하느라 고생했다.","해운대는 생각보다 조용했다."],"story":"어묵 국물로\n손을 녹였다.","photos":["/photos/busan-1.jpg","/photos/busan-2.jpg","/photos/busan-3.jpg","/photos/busan-4.jpg"],"tags":["부산","해운대","설"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f13ea7', '감천 골목을 걷다가', '골목을 돌 때마다 집들이 조금씩 다르게 보였다. 가까이서도 보고 한 발 물러서서도 사진을 남겼다.', array['부산', '감천문화마을', '골목']::text[], '{"kind":"authored-demo","asset":"busan-2.webp","assetTitle":"Gamcheon Culture Village","sourcePostIds":["anon2/busan-1"],"editorial":[{"journeyId":"anon2","id":"busan-1","stopId":"busan","date":"2025-01-24","title":"설 연휴의 해운대","sub":"KTX로 두 시간 반.","heading":"''Busan''의\n겨울 바다","big":["BLUE","WAVE"],"body":["설 연휴라 기차표 구하느라 고생했다.","해운대는 생각보다 조용했다."],"story":"어묵 국물로\n손을 녹였다.","photos":["/photos/busan-1.jpg","/photos/busan-2.jpg","/photos/busan-3.jpg","/photos/busan-4.jpg"],"tags":["부산","해운대","설"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_3af299', '자갈치에서', '자갈치 쪽을 걸었다. 익숙한 곳에서도 카메라를 들면 전에 못 보던 부분이 눈에 들어온다.', array['부산', '자갈치', '시장']::text[], '{"kind":"authored-demo","asset":"busan-4.webp","assetTitle":"Jagalchi Market","sourcePostIds":["anon2/busan-1"],"editorial":[{"journeyId":"anon2","id":"busan-1","stopId":"busan","date":"2025-01-24","title":"설 연휴의 해운대","sub":"KTX로 두 시간 반.","heading":"''Busan''의\n겨울 바다","big":["BLUE","WAVE"],"body":["설 연휴라 기차표 구하느라 고생했다.","해운대는 생각보다 조용했다."],"story":"어묵 국물로\n손을 녹였다.","photos":["/photos/busan-1.jpg","/photos/busan-2.jpg","/photos/busan-3.jpg","/photos/busan-4.jpg"],"tags":["부산","해운대","설"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ca6f69', '부산을 한눈에', '부산타워에서 도시를 둘러봤다. 걸어 다니던 길을 높은 곳에서 다시 찾아봤다.', array['부산', '부산타워', '전망']::text[], '{"kind":"edited-demo","asset":"busan-tower-360.webp","assetTitle":"Busan Tower 360 Degree Panorama 001.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c98ca9', '밤의 동궁과 월지', '해 지고 나서 가야 한다는 말이 맞았다.

물에 비친 불빛이 진짜보다 더 선명했다.

바람이 없어서
물이 거울 같았다.', array['경주', '야경']::text[], '{"kind":"prototype","asset":"gyeongju-1.webp","assetTitle":"Donggung Palace and Wolji Pond","sourcePostIds":["anon2/gyeongju-1"],"editorial":[{"journeyId":"anon2","id":"gyeongju-1","stopId":"gyeongju","date":"2025-01-27","title":"밤의 동궁과 월지","sub":"물에 비친 불빛.","heading":"''Gyeongju''\n천년의 밤","big":["GOLD","NIGHT"],"body":["해 지고 나서 가야 한다는 말이 맞았다.","물에 비친 불빛이 진짜보다 더 선명했다."],"story":"바람이 없어서\n물이 거울 같았다.","photos":["/photos/gyeongju-1.jpg","/photos/gyeongju-2.jpg","/photos/gyeongju-3.jpg","/photos/gyeongju-4.jpg"],"tags":["경주","야경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_a4c7da', '불국사의 돌계단', '불국사의 돌계단 앞에서 잠깐 멈췄다. 서두르지 않고 한 바퀴 돌아보기로 했다.', array['경주', '불국사']::text[], '{"kind":"edited-demo","asset":"gyeongju-2.webp","assetTitle":"Bulguksa","sourcePostIds":["anon2/gyeongju-1"],"editorial":[{"journeyId":"anon2","id":"gyeongju-1","stopId":"gyeongju","date":"2025-01-27","title":"밤의 동궁과 월지","sub":"물에 비친 불빛.","heading":"''Gyeongju''\n천년의 밤","big":["GOLD","NIGHT"],"body":["해 지고 나서 가야 한다는 말이 맞았다.","물에 비친 불빛이 진짜보다 더 선명했다."],"story":"바람이 없어서\n물이 거울 같았다.","photos":["/photos/gyeongju-1.jpg","/photos/gyeongju-2.jpg","/photos/gyeongju-3.jpg","/photos/gyeongju-4.jpg"],"tags":["경주","야경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_066f75', '석굴암에 올라', '석굴암까지 올라왔다. 내려가기 전에 주변 풍경을 한 번 더 둘러봤다.', array['경주', '석굴암']::text[], '{"kind":"edited-demo","asset":"gyeongju-4.webp","assetTitle":"Seokguram","sourcePostIds":["anon2/gyeongju-1"],"editorial":[{"journeyId":"anon2","id":"gyeongju-1","stopId":"gyeongju","date":"2025-01-27","title":"밤의 동궁과 월지","sub":"물에 비친 불빛.","heading":"''Gyeongju''\n천년의 밤","big":["GOLD","NIGHT"],"body":["해 지고 나서 가야 한다는 말이 맞았다.","물에 비친 불빛이 진짜보다 더 선명했다."],"story":"바람이 없어서\n물이 거울 같았다.","photos":["/photos/gyeongju-1.jpg","/photos/gyeongju-2.jpg","/photos/gyeongju-3.jpg","/photos/gyeongju-4.jpg"],"tags":["경주","야경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4ea1ca', '첨성대 옆을 걸었다', '사진으로만 보던 첨성대를 직접 봤다. 주변을 걷다가 조금 떨어진 자리에서도 한 장 남겼다.', array['경주', '첨성대']::text[], '{"kind":"edited-demo","asset":"gyeongju-3.webp","assetTitle":"Cheomseongdae","sourcePostIds":["anon2/gyeongju-1"],"editorial":[{"journeyId":"anon2","id":"gyeongju-1","stopId":"gyeongju","date":"2025-01-27","title":"밤의 동궁과 월지","sub":"물에 비친 불빛.","heading":"''Gyeongju''\n천년의 밤","big":["GOLD","NIGHT"],"body":["해 지고 나서 가야 한다는 말이 맞았다.","물에 비친 불빛이 진짜보다 더 선명했다."],"story":"바람이 없어서\n물이 거울 같았다.","photos":["/photos/gyeongju-1.jpg","/photos/gyeongju-2.jpg","/photos/gyeongju-3.jpg","/photos/gyeongju-4.jpg"],"tags":["경주","야경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_a329d6', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-685610501934afdd.webp","assetTitle":"File:August 2007, walking in Seoul 108.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1b7d39', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-fecf444232db786d.webp","assetTitle":"File:August 2007, walking in Seoul 110.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_78d5c4', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-a31cfdf4a60418bd.webp","assetTitle":"File:August 2007, walking in Seoul 111.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8b9a12', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-1d272fc5d772af16.webp","assetTitle":"File:August 2007, walking in Seoul 114.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_252011', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f5a97317698a69fa.webp","assetTitle":"File:August 2007, walking in Seoul 119.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_74844a', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-046f83bc9294b936.webp","assetTitle":"File:August 2007, walking in Seoul 13.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_be3140', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-cbabd80f855412af.webp","assetTitle":"File:August 2007, walking in Seoul 130.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
