  ('p_29e3ff', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-fc9d04ecfe48074b.webp","assetTitle":"File:Seoul signs by night 4.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_894344', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-d46d6925a819e625.webp","assetTitle":"File:A Rave in Seoul, South Korea in 2001.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b99a33', '멀리서 본 밴쿠버', '가까이에서 걷던 도시를 조금 떨어져서 바라봤다. 건물들이 한 화면에 들어오니 다른 곳처럼 느껴졌다.', array['밴쿠버', '도시풍경']::text[], '{"kind":"authored-demo","asset":"commons-45f5cab8948c806e.webp","assetTitle":"File:Downtown Vancouver skyline (2288740503).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_3c1060', '밴쿠버 첫날, 비가 온다', '공항에서 스카이트레인을 타고 다운타운까지 30분. 워터프런트 역을 나오자마자 기다렸다는 듯이 비가 내리기 시작했다.

숙소는 콜 하버 쪽 작은 아파트. 창밖으로 바다랑 수상비행기가 보여서 짐 풀자마자 한참을 그냥 앉아 있었다.

비 오는 워터프런트를 한참 걸었다.
우산 없이 걷는 사람들이 많아서
나도 그냥 접어 들었다.
저녁엔 연어랑 빵, 그리고 일찍 잠.', array['밴쿠버', '첫날', '콜하버']::text[], '{"kind":"prototype","asset":"vancouver-6.webp","assetTitle":"Coal Harbour","sourcePostIds":["anon1/van-1","anon1/van-12","anon1/van-34","anon1/van-58"],"editorial":[{"journeyId":"anon1","id":"van-1","stopId":"vancouver","date":"2025-01-03","title":"밴쿠버 첫날, 비가 온다","sub":"밴쿠버 첫날, 비가 온다. 두 달 체류의 시작.","heading":"''Vancouver''가 담아낸\n첫날의 풍경","big":["FIRST","DAY"],"body":["공항에서 스카이트레인을 타고 다운타운까지 30분. 워터프런트 역을 나오자마자 기다렸다는 듯이 비가 내리기 시작했다.","숙소는 콜 하버 쪽 작은 아파트. 창밖으로 바다랑 수상비행기가 보여서 짐 풀자마자 한참을 그냥 앉아 있었다."],"story":"비 오는 워터프런트를 한참 걸었다.\n우산 없이 걷는 사람들이 많아서\n나도 그냥 접어 들었다.\n저녁엔 연어랑 빵, 그리고 일찍 잠.","photos":["/photos/vancouver-1.jpg","/photos/vancouver-2.jpg","/photos/vancouver-3.jpg","/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg"],"tags":["밴쿠버","첫날","비","콜하버","숙소뷰"]},{"journeyId":"anon1","id":"van-12","stopId":"vancouver","date":"2025-01-14","title":"그라우스 마운틴 / 스탠리 파크 / 그리고 일상","sub":"곤돌라 대신 그라인드로 올라간 날.","heading":"''Grouse''에서 본\n구름 아래 도시","big":["UP","HILL"],"body":["곤돌라 대신 그라우스 그라인드로 올라갔다. 한 시간 반.","관광지 도장 깨기는 첫 주에 끝내고 나머지는 동네 카페에서 일하고 걷고. 여행이라기보단 잠깐 사는 느낌."],"story":"정상에서 본 밴쿠버는\n구름 아래에 있었다.\n내려오는 길에 들른 폭포가\n오늘의 베스트.","photos":["/photos/vancouver-2.jpg","/photos/vancouver-3.jpg","/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg","/photos/vancouver-8.jpg"],"tags":["밴쿠버","하이킹","스탠리파크"]},{"journeyId":"anon1","id":"van-34","stopId":"vancouver","date":"2025-02-05","title":"밴프 가는 길","sub":"한 달이 벌써 지났다는 걸 믿을 수가 없다.","heading":"''Rockies''로 가는\n아홉 시간","big":["ON","ROCKIES"],"body":["밴프 가는 버스 예약하고 로키 가기 전에 장비 좀 사고.","창밖으로 산이 점점 커지는 걸 아홉 시간 동안 봤다."],"story":"눈이 오기 시작하면\n버스 안이 조용해진다.\n다들 창문에\n이마를 붙이고.","photos":["/photos/vancouver-3.jpg","/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg","/photos/vancouver-8.jpg","/photos/vancouver-1.jpg"],"tags":["로키","버스","설경"]},{"journeyId":"anon1","id":"van-58","stopId":"vancouver","date":"2025-03-01","title":"마지