  ('p_014190', '그랜빌 아일랜드 장보기', '그랜빌 아일랜드에 장을 보러 갔다. 구경하는 시간이 장보는 시간보다 길었다. 돌아오는 길에도 물가에서 한참 머물렀다.', array['밴쿠버', '그랜빌아일랜드', '장보기']::text[], '{"kind":"edited-demo","asset":"vancouver-8.webp","assetTitle":"Granville Island","sourcePostIds":["anon1/van-12","anon1/van-34","anon1/van-58"],"editorial":[{"journeyId":"anon1","id":"van-12","stopId":"vancouver","date":"2025-01-14","title":"그라우스 마운틴 / 스탠리 파크 / 그리고 일상","sub":"곤돌라 대신 그라인드로 올라간 날.","heading":"''Grouse''에서 본\n구름 아래 도시","big":["UP","HILL"],"body":["곤돌라 대신 그라우스 그라인드로 올라갔다. 한 시간 반.","관광지 도장 깨기는 첫 주에 끝내고 나머지는 동네 카페에서 일하고 걷고. 여행이라기보단 잠깐 사는 느낌."],"story":"정상에서 본 밴쿠버는\n구름 아래에 있었다.\n내려오는 길에 들른 폭포가\n오늘의 베스트.","photos":["/photos/vancouver-2.jpg","/photos/vancouver-3.jpg","/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg","/photos/vancouver-8.jpg"],"tags":["밴쿠버","하이킹","스탠리파크"]},{"journeyId":"anon1","id":"van-34","stopId":"vancouver","date":"2025-02-05","title":"밴프 가는 길","sub":"한 달이 벌써 지났다는 걸 믿을 수가 없다.","heading":"''Rockies''로 가는\n아홉 시간","big":["ON","ROCKIES"],"body":["밴프 가는 버스 예약하고 로키 가기 전에 장비 좀 사고.","창밖으로 산이 점점 커지는 걸 아홉 시간 동안 봤다."],"story":"눈이 오기 시작하면\n버스 안이 조용해진다.\n다들 창문에\n이마를 붙이고.","photos":["/photos/vancouver-3.jpg","/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg","/photos/vancouver-8.jpg","/photos/vancouver-1.jpg"],"tags":["로키","버스","설경"]},{"journeyId":"anon1","id":"van-58","stopId":"vancouver","date":"2025-03-01","title":"마지막 주, 짐 싸기","sub":"두 달 치 영수증이랑 엽서를 정리하는 밤.","heading":"''Goodbye''를\n미루는 방법","big":["LAST","WEEK"],"body":["두 달 치 영수증이랑 엽서를 정리하다가 또 사진을 한참 봤다.","다음은 토론토."],"story":"영수증 뒤에 적어 둔\n메모가 많았다.\n대부분 커피였다.","photos":["/photos/vancouver-4.jpg","/photos/vancouver-5.jpg","/photos/vancouver-6.jpg","/photos/vancouver-8.jpg","/photos/vancouver-1.jpg","/photos/vancouver-2.jpg"],"tags":["밴쿠버","마지막주"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c4be0a', '마지막 주, 짐 싸기', '두 달 치 영수증이랑 엽서를 정리하다가 또 사진을 한참 봤다.

영수증 뒤에 적어 둔
메모가 많았다.
