  ('p_606b31', '밴프에 도착해서', '밴프에 도착했다. 멀리 보이는 산 때문에 걷는 동안 자꾸 고개를 들게 된다.', array['밴프', '로키']::text[], '{"kind":"edited-demo","asset":"banff-4.webp","assetTitle":"Banff, Alberta","sourcePostIds":["anon1/banff-1"],"editorial":[{"journeyId":"anon1","id":"banff-1","stopId":"banff","date":"2025-03-06","title":"설경은 반칙이다","sub":"레이크 루이스는 얼어 있었다.","heading":"''Banff''의\n얼어붙은 호수","big":["SNOW","LAKE"],"body":["레이크 루이스는 꽁꽁 얼어 있었다.","호수 위를 걸어서 건넜다."],"story":"숨소리까지\n하얗게 보였다.","photos":["/photos/banff-1.jpg","/photos/banff-2.jpg","/photos/banff-3.jpg","/photos/banff-4.jpg"],"tags":["밴프","설경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_496f15', '로키의 산들', '산을 보다 보니 말수가 줄었다. 어느 쪽으로 카메라를 돌려도 한 장 더 찍고 싶었다.', array['밴프', '로키']::text[], '{"kind":"edited-demo","asset":"banff-1.webp","assetTitle":"Banff National Park","sourcePostIds":["anon1/banff-1"],"editorial":[{"journeyId":"anon1","id":"banff-1","stopId":"banff","date":"2025-03-06","title":"설경은 반칙이다","sub":"레이크 루이스는 얼어 있었다.","heading":"''Banff''의\n얼어붙은 호수","big":["SNOW","LAKE"],"body":["레이크 루이스는 꽁꽁 얼어 있었다.","호수 위를 걸어서 건넜다."],"story":"숨소리까지\n하얗게 보였다.","photos":["/photos/banff-1.jpg","/photos/banff-2.jpg","/photos/banff-3.jpg","/photos/banff-4.jpg"],"tags":["밴프","설경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_bfe8c0', '레이크 루이스 앞에서', '레이크 루이스 앞에서 한참 머물렀다. 호수와 산을 번갈아 보다가 사진을 남겼다.', array['밴프', '레이크루이스']::text[], '{"kind":"edited-demo","asset":"banff-2.webp","assetTitle":"Lake Louise (Alberta)","sourcePostIds":["anon1/banff-1"],"editorial":[{"journeyId":"anon1","id":"banff-1","stopId":"banff","date":"2025-03-06","title":"설경은 반칙이다","sub":"레이크 루이스는 얼어 있었다.","heading":"''Banff''의\n얼어붙은 호수","big":["SNOW","LAKE"],"body":["레이크 루이스는 꽁꽁 얼어 있었다.","호수 위를 걸어서 건넜다."],"story":"숨소리까지\n하얗게 보였다.","photos":["/photos/banff-1.jpg","/photos/banff-2.jpg","/photos/banff-3.jpg","/photos/banff-4.jpg"],"tags":["밴프","설경"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_286991', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-4fe713a0549591e9.webp","assetTitle":"File:August 2007, restaurant in Seoul 2.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_20c404', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-c9676d1fd2304158.webp","assetTitle":"File:August 2007, restaurant in Seoul 3.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e0d194', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-770930609f34152f.webp","assetTitle":"File:August 2007, restaurant in Seoul 4.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f83b86', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-bf205d3cc2d0496f.webp","assetTitle":"File:August 2007, walking in Seoul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c04d15', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-cd3b02d1d4755ecd.webp","assetTitle":"File:August 2007 Seoul by night.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_25fb90', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-de7286f06d899ec7.webp","assetTitle":"File:August 2007 Seoul by night 10.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_18ae40', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-a82cdc76235a5a0c.webp","assetTitle":"File:August 2007 Seoul by night 11.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8a6ac3', '먹고 걷고 먹고', '도톤보리에서 타코야키로 시작.

하루에 만 오천 보, 먹은 건 그보다 많았다.

