  ('p_46acac', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-961f29903459d1ee.webp","assetTitle":"File:Seoul by night 11.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e35e86', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-e804b501fdc60a2c.webp","assetTitle":"File:Seoul by night 4.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_5f46b7', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-da34e3d5a7b9859c.webp","assetTitle":"File:Seoul by night 5.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_fd3ec3', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-22fe579701ddc8ab.webp","assetTitle":"File:Seoul by night 6.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
