  ('p_bc71d4', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-e20c5c18cc5a65f0.webp","assetTitle":"File:Seoul signs by night 11.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e80cbd', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-ea3b2e5fb8d9f78b.webp","assetTitle":"File:Seoul signs by night 12.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c60246', '크리스마스 끝난 파리', '크리스마스가 끝난 파리는 조용했다.

빵집 앞에만 줄이 있었다.

센강 따라
한참 걸었다.', array['파리', '겨울']::text[], '{"kind":"prototype","asset":"paris-1.webp","assetTitle":"Paris","sourcePostIds":["anon1/paris-1"],"editorial":[{"journeyId":"anon1","id":"paris-1","stopId":"paris","date":"2025-12-26","title":"크리스마스 끝난 파리","sub":"파리는 조용했다.","heading":"''Paris''의\n조용한 아침","big":["QUIET","PARIS"],"body":["크리스마스가 끝난 파리는 조용했다.","빵집 앞에만 줄이 있었다."],"story":"센강 따라\n한참 걸었다.","photos":["/photos/paris-1.jpg","/photos/paris-3.jpg","/photos/paris-4.jpg"],"tags":["파리","겨울"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_a17908', '센강 따라', '센강 따라
한참 걸었다.', array['파리', '센강', '산책']::text[], '{"kind":"edited-demo","asset":"paris-3.webp","assetTitle":"Seine","sourcePostIds":["anon1/paris-1"],"editorial":[{"journeyId":"anon1","id":"paris-1","stopId":"paris","date":"2025-12-26","title":"크리스마스 끝난 파리","sub":"파리는 조용했다.","heading":"''Paris''의\n조용한 아침","big":["QUIET","PARIS"],"body":["크리스마스가 끝난 파리는 조용했다.","빵집 앞에만 줄이 있었다."],"story":"센강 따라\n한참 걸었다.","photos":["/photos/paris-1.jpg","/photos/paris-3.jpg","/photos/paris-4.jpg"],"tags":["파리","겨울"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4a90b2', '루브르 앞에서', '루브르 앞을 천천히 걸었다. 돌아서기 전에 한 번 더 사진을 찍었다.', array['파리', '루브르']::text[], '{"kind":"edited-demo","asset":"paris-4.webp","assetTitle":"Louvre","sourcePostIds":["anon1/paris-1"],"editorial":[{"journeyId":"anon1","id":"paris-1","stopId":"paris","date":"2025-12-26","title":"크리스마스 끝난 파리","sub":"파리는 조용했다.","heading":"''Paris''의\n조용한 아침","big":["QUIET","PARIS"],"body":["크리스마스가 끝난 파리는 조용했다.","빵집 앞에만 줄이 있었다."],"story":"센강 따라\n한참 걸었다.","photos":["/photos/paris-1.jpg","/photos/paris-3.jpg","/photos/paris-4.jpg"],"tags":["파리","겨울"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_677fcc', '유로스타로 런던', '파리에서 유로스타로 넘어왔다.

오후 네 시에 해가 졌다.

펍 불빛이
더 따뜻해 보였다.', array['런던', '기차']::text[], '{"kind":"prototype","asset":"london-4.webp","assetTitle":"Eurostar","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c9403e', '타워 브리지 앞에서', '다리 앞에 서서 강 건너를 한참 봤다. 지도를 덮고 강을 따라 조금 더 걷기로 했다.', array['런던', '타워브리지', '산책']::text[], '{"kind":"edited-demo","asset":"london-2.webp","assetTitle":"Tower Bridge","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8d0d6f', '빅벤을 올려다보다', '멀리서 보던 시계탑을 바로 앞에서 올려다봤다. 사진 한 장을 찍고도 쉽게 자리를 뜨지 못했다.', array['런던', '빅벤']::text[], '{"kind":"edited-demo","asset":"london-3.webp","assetTitle":"Big Ben","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_fa9e4a', '해가 네 시면 진다', '파리에서 유로스타로 넘어왔다.

