  ('p_405d61', '바르셀로나를 걷다', '걷는 동안 건물들을 자꾸 올려다봤다. 목적지까지 가는 길도 구경할 것이 많았다.', array['바르셀로나', '산책']::text[], '{"kind":"edited-demo","asset":"barcelona-1.webp","assetTitle":"Barcelona","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b19296', '가우디는 이상하고 좋다', '사그라다 파밀리아 안에서 한참 위만 봤다.

빛이 색깔을 바꾸며 들어왔다.

직선이
하나도 없었다.', array['바르셀로나', '건축']::text[], '{"kind":"prototype","asset":"barcelona-2.webp","assetTitle":"Sagrada Família","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_d6a09c', '구엘 공원의 곡선', '구엘 공원을 걸었다. 모양과 색을 보다 보니 사진을 찍는 시간이 길어졌다.', array['바르셀로나', '구엘공원']::text[], '{"kind":"edited-demo","asset":"barcelona-3.webp","assetTitle":"Park Güell","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f3ecba', '카사 바트요 앞에서', '카사 바트요를 한참 올려다봤다. 곧은 선을 찾는 것보다 구불구불한 모양을 따라 보는 편이 쉬웠다.', array['바르셀로나', '카사바트요']::text[], '{"kind":"edited-demo","asset":"barcelona-4.webp","assetTitle":"Casa Batlló","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6e33c3', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f0d697b6c38c4376.webp","assetTitle":"File:Seoul signs by night 13.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
