  ('p_85203e', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-e0df41c4f7f2755a.webp","assetTitle":"File:Seoul signs by night 15.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8c66b9', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-5c7c440f539a6241.webp","assetTitle":"File:Seoul signs by night 16.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
