  ('p_8fce4e', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-0ec99e0146ba305b.webp","assetTitle":"File:Seoul Outdoor Library by Cheonggyecheon stream 2025-10-25 02.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c1e96f', '여수에서 보낸 오후', '여수에 도착해서 천천히 걸었다. 바다 가까운 도시에서는 자꾸 물가 쪽으로 발길이 간다.', array['여수']::text[], '{"kind":"edited-demo","asset":"yeosu-1.webp","assetTitle":"Yeosu","sourcePostIds":["anon2/yeosu-1"],"editorial":[{"journeyId":"anon2","id":"yeosu-1","stopId":"yeosu","date":"2026-03-20","title":"여수 밤바다","sub":"노래가 괜히 나온 게 아니었다.","heading":"''Yeosu''의\n밤바다","big":["NIGHT","SEA"],"body":["케이블카 타고 돌산까지.","포차 거리에서 딱새우회."],"story":"노래를 흥얼거리는\n사람이 나만은 아니었다.","photos":["/photos/yeosu-1.jpg","/photos/yeosu-2.jpg","/photos/yeosu-3.jpg"],"tags":["여수","밤바다"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_a7958b', '오동도 한 바퀴', '오동도를 한 바퀴 걸었다. 들어갈 때보다 돌아오는 길이 짧게 느껴졌다.', array['여수', '오동도']::text[], '{"kind":"edited-demo","asset":"yeosu-2.webp","assetTitle":"Odongdo","sourcePostIds":["anon2/yeosu-1"],"editorial":[{"journeyId":"anon2","id":"yeosu-1","stopId":"yeosu","date":"2026-03-20","title":"여수 밤바다","sub":"노래가 괜히 나온 게 아니었다.","heading":"''Yeosu''의\n밤바다","big":["NIGHT","SEA"],"body":["케이블카 타고 돌산까지.","포차 거리에서 딱새우회."],"story":"노래를 흥얼거리는\n사람이 나만은 아니었다.","photos":["/photos/yeosu-1.jpg","/photos/yeosu-2.jpg","/photos/yeosu-3.jpg"],"tags":["여수","밤바다"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_aeb3bc', '향일암에서 맞은 아침', '향일암에 올라왔다. 일찍 나선 덕분에 오래 바라볼 시간이 있었다.', array['여수', '향일암']::text[], '{"kind":"edited-demo","asset":"yeosu-3.webp","assetTitle":"Hyangiram","sourcePostIds":["anon2/yeosu-1"],"editorial":[{"journeyId":"anon2","id":"yeosu-1","stopId":"yeosu","date":"2026-03-20","title":"여수 밤바다","sub":"노래가 괜히 나온 게 아니었다.","heading":"''Yeosu''의\n밤바다","big":["NIGHT","SEA"],"body":["케이블카 타고 돌산까지.","포차 거리에서 딱새우회."],"story":"노래를 흥얼거리는\n사람이 나만은 아니었다.","photos":["/photos/yeosu-1.jpg","/photos/yeosu-2.jpg","/photos/yeosu-3.jpg"],"tags":["여수","밤바다"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_cd07f6', '선암사에서', '선암사에 들렀다. 사진을 찍고 카메라를 내려놓은 뒤에도 한참 둘러봤다.', array['순천', '선암사']::text[], '{"kind":"edited-demo","asset":"suncheon-6.webp","assetTitle":"Seonamsa","sourcePostIds":["anon2/suncheon-1"],"editorial":[{"journeyId":"anon2","id":"suncheon-1","stopId":"suncheon","date":"2026-03-23","title":"순천만 갈대밭","sub":"해 질 녘이 제일.","heading":"''Suncheon''\n갈대 사이로","big":["GOLD","REEDS"],"body":["버스 타고 사십 분.","용산전망대까지 걸어 올라갔다."],"story":"바람 불 때마다\n갈대가 한쪽으로 누웠다.","photos":["/photos/suncheon-4.jpg","/photos/suncheon-5.jpg","/photos/suncheon-6.jpg"],"tags":["순천","갈대"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1f8c47', '송광사 가는 길', '송광사를 둘러보며 천천히 걸었다. 다음 장소로 바로 넘어가지 않고 조금 더 머물렀다.', array['순천', '송광사']::text[], '{"kind":"edited-demo","asset":"suncheon-4.webp","assetTitle":"Songgwangsa","sourcePostIds":["anon2/suncheon-1"],"editorial":[{"journeyId":"anon2","id":"suncheon-1","stopId":"suncheon","date":"2026-03-23","title":"순천만 갈대밭","sub":"해 질 녘이 제일.","heading":"''Suncheon''\n갈대 사이로","big":["GOLD","REEDS"],"body":["버스 타고 사십 분.","용산전망대까지 걸어 올라갔다."],"story":"바람 불 때마다\n갈대가 한쪽으로 누웠다.","photos":["/photos/suncheon-4.jpg","/photos/suncheon-5.jpg","/photos/suncheon-6.jpg"],"tags":["순천","갈대"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_506e1a', '순천에서 잠깐', '순천에서 보낸 시간을 한 장 남겼다. 오래 걷고 나니 처음보다 주변을 더 자세히 보게 됐다.', array['순천', '산책']::text[], '{"kind":"edited-demo","asset":"suncheon-5.webp","assetTitle":"Suncheon","sourcePostIds":["anon2/suncheon-1"],"editorial":[{"journeyId":"anon2","id":"suncheon-1","stopId":"suncheon","date":"2026-03-23","title":"순천만 갈대밭","sub":"해 질 녘이 제일.","heading":"''Suncheon''\n갈대 사이로","big":["GOLD","REEDS"],"body":["버스 타고 사십 분.","용산전망대까지 걸어 올라갔다."],"story":"바람 불 때마다\n갈대가 한쪽으로 누웠다.","photos":["/photos/suncheon-4.jpg","/photos/suncheon-5.jpg","/photos/suncheon-6.jpg"],"tags":["순천","갈대"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1f0f26', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-6b0f278248ca8a2b.webp","assetTitle":"File:Seoul Outdoor Library by Cheonggyecheon stream 2025-10-25 03.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
