  ('p_31cd3f', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f8e116fad71e4006.webp","assetTitle":"File:UK Government and the Republic of Korea host AI Summit in Seoul, Korea on 22 May 2024 - 8.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8a5b48', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-de6ded88c4509173.webp","assetTitle":"File:WikiConference Seoul 2025-05 View.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_336680', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-709978bc6da91616.webp","assetTitle":"File:여의공원로 2025 (Yeouigongwon-ro, Yeongdeungpo-gu, Seoul).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1eb564', '속초에서 쉬어 가기', '걷다가 잠깐 쉬었다. 다음 일정을 정하기 전에 지금 있는 곳부터 조금 더 보기로 했다.', array['속초']::text[], '{"kind":"edited-demo","asset":"sokcho-3.webp","assetTitle":"Sokcho","sourcePostIds":["anon2/sokcho-1"],"editorial":[{"journeyId":"anon2","id":"sokcho-1","stopId":"sokcho","date":"2026-08-14","title":"설악산 흔들바위","sub":"저녁엔 물회.","heading":"''Seorak''의\n흔들바위","big":["ROCK","ROLL"],"body":["케이블카 줄이 길어서 그냥 걸었다.","흔들바위는 정말 흔들리는 것 같았다."],"story":"내려와서 먹은 물회가\n제일 기억에 남는다.","photos":["/photos/sokcho-1.jpg","/photos/sokcho-2.jpg","/photos/sokcho-3.jpg","/photos/sokcho-4.jpg"],"tags":["속초","설악산"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ea2e56', '신흥사를 지나', '신흥사를 둘러보고 내려왔다. 산에서 보낸 시간이 생각보다 길었다.', array['속초', '신흥사']::text[], '{"kind":"edited-demo","asset":"sokcho-4.webp","assetTitle":"Sinheungsa","sourcePostIds":["anon2/sokcho-1"],"editorial":[{"journeyId":"anon2","id":"sokcho-1","stopId":"sokcho","date":"2026-08-14","title":"설악산 흔들바위","sub":"저녁엔 물회.","heading":"''Seorak''의\n흔들바위","big":["ROCK","ROLL"],"body":["케이블카 줄이 길어서 그냥 걸었다.","흔들바위는 정말 흔들리는 것 같았다."],"story":"내려와서 먹은 물회가\n제일 기억에 남는다.","photos":["/photos/sokcho-1.jpg","/photos/sokcho-2.jpg","/photos/sokcho-3.jpg","/photos/sokcho-4.jpg"],"tags":["속초","설악산"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_98c669', '울산바위를 보며', '울산바위를 올려다봤다. 사진 안에 다 담으려다가 그냥 눈으로도 오래 보기로 했다.', array['속초', '울산바위']::text[], '{"kind":"edited-demo","asset":"sokcho-2.webp","assetTitle":"Ulsanbawi","sourcePostIds":["anon2/sokcho-1"],"editorial":[{"journeyId":"anon2","id":"sokcho-1","stopId":"sokcho","date":"2026-08-14","title":"설악산 흔들바위","sub":"저녁엔 물회.","heading":"''Seorak''의\n흔들바위","big":["ROCK","ROLL"],"body":["케이블카 줄이 길어서 그냥 걸었다.","흔들바위는 정말 흔들리는 것 같았다."],"story":"내려와서 먹은 물회가\n제일 기억에 남는다.","photos":["/photos/sokcho-1.jpg","/photos/sokcho-2.jpg","/photos/sokcho-3.jpg","/photos/sokcho-4.jpg"],"tags":["속초","설악산"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_a9e014', '설악산 흔들바위', '케이블카 줄이 길어서 그냥 걸었다.

흔들바위는 정말 흔들리는 것 같았다.

내려와서 먹은 물회가
제일 기억에 남는다.', array['속초', '설악산']::text[], '{"kind":"prototype","asset":"sokcho-1.webp","assetTitle":"Seoraksan","sourcePostIds":["anon2/sokcho-1"],"editorial":[{"journeyId":"anon2","id":"sokcho-1","stopId":"sokcho","date":"2026-08-14","title":"설악산 흔들바위","sub":"저녁엔 물회.","heading":"''Seorak''의\n흔들바위","big":["ROCK","ROLL"],"body":["케이블카 줄이 길어서 그냥 걸었다.","흔들바위는 정말 흔들리는 것 같았다."],"story":"내려와서 먹은 물회가\n제일 기억에 남는다.","photos":["/photos/sokcho-1.jpg","/photos/sokcho-2.jpg","/photos/sokcho-3.jpg","/photos/sokcho-4.jpg"],"tags":["속초","설악산"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c0c0e1', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-36eb1de6413a68b1.webp","assetTitle":"File:여의공원로 전경 2025 (Yeouigongwon-ro, Yeongdeungpo-gu, Seoul).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_ce8a3e', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-0c7c554efb442947.webp","assetTitle":"File:02025 Gyeongbokgung.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_68ad76', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-ba1f784aead18629.webp","assetTitle":"File:August 2007, restaurant in Seoul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_7b408c', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-ef4e178bf6afadee.webp","assetTitle":"File:Cheonggeyechon River in Seoul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_2bdde1', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-437fc9c7002d58ea.webp","assetTitle":"File:Gwangjang Market, Seoul 02.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_7bd463', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-23cd90fb05f0c316.webp","assetTitle":"File:Gyeongbokgung Palace, Seoul, 1395 (79) (26258404627).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_412fd8', '해협 건너는 배에서', '페리 표 한 장으로 대륙을 건넜다.

갈매기가 빵을 받아먹었다.

노을이
모스크 뒤로.', array['이스탄불', '페리']::text[], '{"kind":"prototype","asset":"istanbul-1.webp","assetTitle":"Istanbul","sourcePostIds":["anon1/istanbul-1"],"editorial":[{"journeyId":"anon1","id":"istanbul-1","stopId":"istanbul","date":"2026-01-18","title":"해협 건너는 배에서","sub":"차 한 잔 들고 유럽에서 아시아로.","heading":"''Istanbul''\n두 대륙 사이","big":["TWO","SHORES"],"body":["페리 표 한 장으로 대륙을 건넜다.","갈매기가 빵을 받아먹었다."],"story":"노을이\n모스크 뒤로.","photos":["/photos/istanbul-1.jpg","/photos/istanbul-2.jpg","/photos/istanbul-4.jpg"],"tags":["이스탄불","페리"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e424f1', '아야 소피아를 보며', '아야 소피아 앞에 섰다. 멀리서 보던 모습과 가까이에서 보이는 부분을 번갈아 사진에 남겼다.', array['이스탄불', '아야소피아']::text[], '{"kind":"edited-demo","asset":"istanbul-2.webp","assetTitle":"Hagia Sophia","sourcePostIds":["anon1/istanbul-1"],"editorial":[{"journeyId":"anon1","id":"istanbul-1","stopId":"istanbul","date":"2026-01-18","title":"해협 건너는 배에서","sub":"차 한 잔 들고 유럽에서 아시아로.","heading":"''Istanbul''\n두 대륙 사이","big":["TWO","SHORES"],"body":["페리 표 한 장으로 대륙을 건넜다.","갈매기가 빵을 받아먹었다."],"story":"노을이\n모스크 뒤로.","photos":["/photos/istanbul-1.jpg","/photos/istanbul-2.jpg","/photos/istanbul-4.jpg"],"tags":["이스탄불","페리"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6e7779', '아야 소피아 앞에서', '아야 소피아를 바라보다가 사진을 남겼다. 가까이에서 보니 눈에 들어오는 부분이 더 많았다.', array['이스탄불', '아야소피아']::text[], '{"kind":"authored-demo","asset":"commons-8d3a68f7426678e7.webp","assetTitle":"File:2012-12-08 Hagia Sophia Istanbul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_962143', '갈라타 탑을 찾아서', '골목을 따라 갈라타 탑까지 걸었다. 탑을 보고 내려오는 길에도 자꾸 뒤를 돌아봤다.', array['이스탄불', '갈라타탑']::text[], '{"kind":"edited-demo","asset":"istanbul-4.webp","assetTitle":"Galata Tower","sourcePostIds":["anon1/istanbul-1"],"editorial":[{"journeyId":"anon1","id":"istanbul-1","stopId":"istanbul","date":"2026-01-18","title":"해협 건너는 배에서","sub":"차 한 잔 들고 유럽에서 아시아로.","heading":"''Istanbul''\n두 대륙 사이","big":["TWO","SHORES"],"body":["페리 표 한 장으로 대륙을 건넜다.","갈매기가 빵을 받아먹었다."],"story":"노을이\n모스크 뒤로.","photos":["/photos/istanbul-1.jpg","/photos/istanbul-2.jpg","/photos/istanbul-4.jpg"],"tags":["이스탄불","페리"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_17dba5', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-1a7cc15507e8175b.webp","assetTitle":"File:Gyeonghoeru (Royal Banquet Hall) at Gyeongbokgung Palace, Seoul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_69ff61', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-6a0349e10ba4b08e.webp","assetTitle":"File:Hapjeong, Seoul (2).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_9c4738', '서울에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-ab9658ccb2d94e21.webp","assetTitle":"File:Huijeongdang Hall interior through open doors at Changdeokgung Palace in Seoul.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_28439e', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-402c291419665c1d.webp","assetTitle":"File:ITX Maum in Seoul Station (2026).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_8f8a0a', '걷던 길의 기록', '서울에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f5b3c11260221073.webp","assetTitle":"File:KOCIS Cheonggyecheon (stream) in Seoul (7085878459).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e2730c', '오늘의 서울', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-5ebca1cdef4610b0.webp","assetTitle":"File:Lee Ko – A Way Coming Back ArtPop billboard, Jamsil, Seoul, South Korea.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_433946', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-11dc74598b4d5482.webp","assetTitle":"File:Lee Ko – A Way Coming Back ArtPop billboard, Myeongdong, Seoul, South Korea.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_4b44fe', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-9a24d6b42a660220.webp","assetTitle":"File:Lee Ko – A Way Coming Back ArtPop billboard, Seoul, South Korea.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_53a91b', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-dc02ef1a8dc86aac.webp","assetTitle":"File:Lee Ko – A Way Coming Back digital billboard display, Myeongdong, Seoul, South Korea.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_caa566', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-8ec02514056b60c7.webp","assetTitle":"File:Onew performing at SM Town Live ''10 World Tour in Seoul 06.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_3f1b5f', '길에서 보낸 시간', '목적지만 보고 다니지 않기로 했다. 걷는 동안 눈에 들어온 것들도 조금씩 남겨 둔다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-9fa319aef8e0ac40.webp","assetTitle":"File:Seoul, Korea April 2014 (13967318215).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_c91209', '잠깐 멈춘 자리', '그냥 지나가려다가 카메라를 꺼냈다. 익숙한 길도 가끔은 조금 천천히 보고 싶어진다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-1e2d7ff8eea81754.webp","assetTitle":"File:Seoul-Yangyang Expwy SChuncheon IC Exit(IC to TG).jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_99232d', '멀리서 본 서울', '가까이에서 걷던 도시를 조금 떨어져서 바라봤다. 건물들이 한 화면에 들어오니 다른 곳처럼 느껴졌다.', array['서울', '도시풍경']::text[], '{"kind":"authored-demo","asset":"commons-40adde5388877f52.webp","assetTitle":"File:Seoul Aerial Shot 11.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_96cf36', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['서울', '산책']::text[], '{"kind":"authored-demo","asset":"commons-15c987145398685b.webp","assetTitle":"File:Seoul on way to airport.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00');

