  ('p_d8b0ec', '오늘의 부산', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-905f8047cdacfa51.webp","assetTitle":"File:Busan beach 3.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_0d0e00', '부산에서 남긴 한 장', '걷다가 눈에 들어온 풍경을 남겼다. 특별한 목적지 없이 다닌 길도 사진으로 보니 기억에 남는다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-018a08c04a8c1b02.webp","assetTitle":"File:Busan ferry terminal.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
