  ('p_a9e0fe', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-e99fbe819d7c0920.webp","assetTitle":"File:Busan ferry terminal 16.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
