  ('p_dabafe', '런던에서 보낸 첫날', '런던에서의 첫날. 짐을 내려놓고 근처부터 걸어 봤다. 앞으로 자주 다니게 될 길을 한 장 남겼다.', array['런던', '첫날', '여름']::text[], '{"kind":"adapted-prototype","asset":"london-1.webp","assetTitle":"London","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_e3fc77', '타워 브리지 앞에서', '다리 앞에 서서 강 건너를 한참 봤다. 지도를 덮고 강을 따라 조금 더 걷기로 했다.', array['런던', '타워브리지', '산책']::text[], '{"kind":"edited-demo","asset":"london-2.webp","assetTitle":"Tower Bridge","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6936a2', '빅벤을 올려다보다', '멀리서 보던 시계탑을 바로 앞에서 올려다봤다. 사진 한 장을 찍고도 쉽게 자리를 뜨지 못했다.', array['런던', '빅벤']::text[], '{"kind":"edited-demo","asset":"london-3.webp","assetTitle":"Big Ben","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_57d4a2', '런던을 떠나는 아침', '런던을 떠나는 아침에 역에서 한 장 남겼다. 처음에는 낯설던 곳들이 벌써 조금 익숙해졌다.', array['런던', '기차', '마지막날']::text[], '{"kind":"adapted-prototype","asset":"london-4.webp","assetTitle":"Eurostar","sourcePostIds":["anon1/london-1"],"editorial":[{"journeyId":"anon1","id":"london-1","stopId":"london","date":"2026-01-03","title":"해가 네 시면 진다","sub":"유로스타로 두 시간 십육 분.","heading":"''London''의\n이른 저녁","big":["EARLY","DARK"],"body":["파리에서 유로스타로 넘어왔다.","오후 네 시에 해가 졌다."],"story":"펍 불빛이\n더 따뜻해 보였다.","photos":["/photos/london-1.jpg","/photos/london-2.jpg","/photos/london-3.jpg","/photos/london-4.jpg"],"tags":["런던","기차"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
