  ('p_7d74cb', '파리 마지막 날', '떠나기 전에 루브르 앞을 다시 걸었다. 마지막이라고 생각하니 평소보다 천천히 보게 됐다. 돌아가기 전에 사진을 한 장 더 남겼다.', array['파리', '루브르', '마지막날']::text[], '{"kind":"adapted-prototype","asset":"paris-4.webp","assetTitle":"Louvre","sourcePostIds":["anon1/paris-1"],"editorial":[{"journeyId":"anon1","id":"paris-1","stopId":"paris","date":"2025-12-26","title":"크리스마스 끝난 파리","sub":"파리는 조용했다.","heading":"''Paris''의\n조용한 아침","big":["QUIET","PARIS"],"body":["크리스마스가 끝난 파리는 조용했다.","빵집 앞에만 줄이 있었다."],"story":"센강 따라\n한참 걸었다.","photos":["/photos/paris-1.jpg","/photos/paris-3.jpg","/photos/paris-4.jpg"],"tags":["파리","겨울"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
