  ('p_9ffc6a', '걷던 길의 기록', '부산에서 걷던 길을 남겼다. 돌아와 사진을 보니 어디서 멈췄는지 먼저 떠오른다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-1d27db1c5694d0f3.webp","assetTitle":"File:Busan fishing harbor at night 4.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_91e81c', '오늘의 부산', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-c4d786a4c6bc1daa.webp","assetTitle":"File:Street views in Busan 3.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_2edd86', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-1ab197527696ed2f.webp","assetTitle":"File:August 2007 Busan fishing harbour 11.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_6390ec', '오늘의 부산', '오늘 걸었던 곳을 한 장 남겼다. 비슷하게 지나가는 날들 사이에 이런 장면이 하나씩 쌓인다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-f3c9b3165ccc716b.webp","assetTitle":"File:August 2007 Busan fishing harbour 15.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_97d0f0', '바르셀로나를 걷다', '걷는 동안 건물들을 자꾸 올려다봤다. 목적지까지 가는 길도 구경할 것이 많았다.', array['바르셀로나', '산책']::text[], '{"kind":"edited-demo","asset":"barcelona-1.webp","assetTitle":"Barcelona","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_b991e4', '가우디는 이상하고 좋다', '사그라다 파밀리아 안에서 한참 위만 봤다.

