  ('p_45c1cb', '구엘 공원의 곡선', '구엘 공원을 걸었다. 모양과 색을 보다 보니 사진을 찍는 시간이 길어졌다.', array['바르셀로나', '구엘공원']::text[], '{"kind":"edited-demo","asset":"barcelona-3.webp","assetTitle":"Park Güell","sourcePostIds":["anon1/barcelona-1"],"editorial":[{"journeyId":"anon1","id":"barcelona-1","stopId":"barcelona","date":"2026-01-09","title":"가우디는 이상하고 좋다","sub":"사진보다 훨씬 이상하고 훨씬 좋다.","heading":"''Barcelona''의\n곡선들","big":["ODD","GAUDI"],"body":["사그라다 파밀리아 안에서 한참 위만 봤다.","빛이 색깔을 바꾸며 들어왔다."],"story":"직선이\n하나도 없었다.","photos":["/photos/barcelona-1.jpg","/photos/barcelona-2.jpg","/photos/barcelona-3.jpg","/photos/barcelona-4.jpg"],"tags":["바르셀로나","건축"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
