  ('p_fb6dfb', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-44c8f19298e2e73f.webp","assetTitle":"File:Busan fishing harbor at night 17.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
