  ('p_7f87e5', '돌아오는 길에', '돌아오다가 잠깐 멈췄다. 사진을 찍고 나서야 다시 발걸음을 옮겼다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-2153fda7dcd0a2bf.webp","assetTitle":"File:Busan fishing harbor at night 20.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
