  ('p_ad3be5', '브루클린 브리지를 건너며', '다리 위에서 도시 쪽을 돌아봤다. 건너는 동안에도 몇 번이나 멈춰 사진을 찍었다.', array['뉴욕', '브루클린브리지']::text[], '{"kind":"edited-demo","asset":"newyork-4.webp","assetTitle":"Brooklyn Bridge","sourcePostIds":["anon1/newyork-1"],"editorial":[{"journeyId":"anon1","id":"newyork-1","stopId":"newyork","date":"2025-03-23","title":"서울에서 가장 멀리","sub":"11,070km, 그리고 일주일.","heading":"''New York''의\n밤 거리","big":["FAR","AWAY"],"body":["토론토에서 버스를 타고 넘어왔다.","밤 열 시에도 거리가 낮처럼 밝았다."],"story":"걷다 보면\n영화 속 같은 장면.","photos":["/photos/newyork-1.jpg","/photos/newyork-2.jpg","/photos/newyork-3.jpg","/photos/newyork-4.jpg"],"tags":["뉴욕","밤"]}],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_1c6b33', '한 번 더 둘러보기', '서둘러 지나치지 않고 주변을 조금 더 봤다. 찍을까 말까 하던 사진이 오히려 오래 남는다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-c8e670789e2fcada.webp","assetTitle":"File:August 2007 Busan fishing harbour 18.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
  ('p_f0103e', '별일 없던 날의 사진', '특별한 일은 없었지만 사진은 남겼다. 나중에는 이런 평범한 날이 더 궁금해질 것 같다.', array['부산', '산책']::text[], '{"kind":"authored-demo","asset":"commons-b1b859a65337cb61.webp","assetTitle":"File:August 2007 Busan fishing harbour 2.jpg","sourcePostIds":[],"editorial":[],"notice":"합성 데모용 글. 원문 날짜는 현재 사진의 촬영일과 다를 수 있다."}'::jsonb, '2026-10-31T12:00:00+09:00'),
